<script setup lang="ts">import { onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { useProfileStore } from '../stores/profile';import type { Profile } from '../types';import ProfilePreview from '../components/ProfilePreview.vue';const route=useRoute(),store=useProfileStore(),profile=ref<Profile|null>(),loading=ref(true);onMounted(async()=>{profile.value=await store.loadPublic(String(route.params.slug));loading.value=false})</script>
<template><main class="public-wrap"><div v-if="loading" class="public-message">Opening profile…</div><ProfilePreview v-else-if="profile" :profile="profile" interactive/><div v-else class="public-message"><b>Profile not found</b><p>This page may still be a draft or its address has changed.</p><a href="/">Create your own LinkCard</a></div></main></template>

